export const LEGACY_TRACE_NAMES: Record<string, string> = {
  "bi_list_measures": "bi_schema",
  "bi_list_dimensions": "bi_schema",
};

/** 旧名 → 现名。工具改名的读路径规范化表（后端同名表的 TS 投影）。 */
export const TOOL_RENAMES: Record<string, string> = {
  "bi_ask_question": "bi_query",
  "canvas_add_chart": "add_chart",
  "canvas_add_image": "add_image",
};

/** 旧名 → 现名。历史 trace 里存的是当时的名字，查表前先过这里。 */
/** 不吃 LEGACY_TRACE_NAMES —— 那是双注册旧名，语义不同（见后端同名注释）。 */
export function canonicalToolName(name: string): string {
  return TOOL_RENAMES[name] ?? name;
}
